head.script:
scwin.cob_idntNum_onafteredit = function() {
    edt_exgNum.focus();
}
scwin.unitTest = function() {
    //init
    // WebSquare.wUnit.start();
    //Test step 1. Source 탭에서 empty 가 true 인지 확인한다.
    //1. In the Source tab, verify that empty is true.
    //Verify step 1. emptyItem = "true"
    //Test step 2. 브라우저에서 autoComplete 를 클릭한다.
    //2. In the browser, click autoComplete.
    //Verify step 2. The first data of autoComplete becomes edit mode.
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('cob_idntNum_label').click()");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("assert", "WebSquare.wUnit.getJq('#cob_idntNum_input').css('display')", "block");
    WebSquare.wUnit.addCommand("pause", "500");
    //Test step 3. autoComplete 의 첫번째 데이터를 지우고 Tab 키 또는 맨밑에 inputBox 를 선택한다.
    //3. Clear the first data of autoComplete and select Tab or inputBox at the bottom.
    //Verify step 3. Focus is moved to the bottom of the inputBox.
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getJq('#cob_idntNum_input').val('')");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('edt_exgNum').focus()");
    WebSquare.wUnit.addCommand("pause", "500");
    //Test step 4. 다시 autoComplete 를 클릭한다.
    //4. Click autoComplete again.
    //Verify step 4. The first data of autoComplete becomes edit mode.
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('cob_idntNum_label').click()");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("assert", "WebSquare.wUnit.getJq('#cob_idntNum_input').css('display') == 'block'", "true");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("assert", "WebSquare.wUnit.getJq('#cob_idntNum_input').val() == ''", "true");
    WebSquare.wUnit.addCommand("pause", "500");
    //Run  and stop
    WebSquare.wUnit.run();
    WebSquare.wUnit.stop();
}
scwin.onpageload2 = function() {
    if (typeof scwin.onpageload === "function") {
        scwin.onpageload();
    }
    //Function 
    //Created by: Thuyet.Pham
    //Created date: 28-Feb-2018
    if (typeof scwin.unitTest === "function") {
        scwin.unitTest();
    }
}
